# skillsync completion (generated by skillsync @VERSION@; do not edit)

$skillsyncData = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::Ordinal)
$skillsyncData.Add('S|', @('link', 'skills'))
$skillsyncData.Add('F|', @('--help', '--version', '-h'))
$skillsyncData.Add('Q|', @())
$skillsyncData.Add('S|link', @())
$skillsyncData.Add('F|link', @('--direct', '--help', '--json', '--mode', '--out-dir', '--tag', '--target-file', '-h', '-t'))
$skillsyncData.Add('Q|link', @())
$skillsyncData.Add('P|link', 'path')
$skillsyncData.Add('K|link|--mode', 'choices')
$skillsyncData.Add('C|link|--mode', @('copy', 'it''s', 'two words'))
$skillsyncData.Add('K|link|--out-dir', 'path')
$skillsyncData.Add('K|link|--target-file', 'path')
$skillsyncData.Add('K|link|--direct', 'value')
$skillsyncData.Add('K|link|--tag', 'value')
$skillsyncData.Add('K|link|-t', 'value')
$skillsyncData.Add('S|skills', @('add', 'list'))
$skillsyncData.Add('F|skills', @('--help', '-h'))
$skillsyncData.Add('Q|skills', @())
$skillsyncData.Add('S|skills add', @())
$skillsyncData.Add('F|skills add', @('--force', '--help', '-h'))
$skillsyncData.Add('Q|skills add', @('alpha', 'beta'))
$skillsyncData.Add('S|skills list', @())
$skillsyncData.Add('F|skills list', @('--help', '-h'))
$skillsyncData.Add('Q|skills list', @())

$skillsyncComplete = {
    param($wordToComplete, $commandAst, $cursorPosition)
    $words = @($commandAst.CommandElements | ForEach-Object { $_.ToString().Trim([char]39, [char]34) })
    if ($wordToComplete -ne '' -and $words.Count -gt 1) {
        $words = @($words[0..($words.Count - 2)])
    }
    $node = ''
    for ($i = 1; $i -lt $words.Count; $i++) {
        $w = $words[$i]
        if ($w.StartsWith('-')) {
            if ($skillsyncData.ContainsKey("K|$node|$w")) { $i++ }
        } elseif ($skillsyncData["S|$node"] -ccontains $w) {
            if ($node -eq '') { $node = $w } else { $node = "$node $w" }
        }
    }
    $prev = ''
    if ($words.Count -gt 1) { $prev = $words[$words.Count - 1] }
    if ($prev.StartsWith('-') -and $skillsyncData.ContainsKey("K|$node|$prev")) {
        if ($skillsyncData["K|$node|$prev"] -ne 'choices') { return }
        $items = @($skillsyncData["C|$node|$prev"])
    } elseif ($wordToComplete.StartsWith('-')) {
        $items = @($skillsyncData["F|$node"])
    } else {
        $items = @($skillsyncData["S|$node"]) + @($skillsyncData["Q|$node"])
    }
    foreach ($item in $items) {
        if ($item.StartsWith($wordToComplete, [System.StringComparison]::OrdinalIgnoreCase)) {
            $text = $item
            if ($text -match '[\s''"]') { $text = "'" + $text.Replace("'", "''") + "'" }
            [System.Management.Automation.CompletionResult]::new($text, $item, 'ParameterValue', $item)
        }
    }
}
Register-ArgumentCompleter -Native -CommandName skillsync -ScriptBlock $skillsyncComplete.GetNewClosure()
